const allItems = $input.all().filter(item => item.json.position); // skip metadata row

// Limit to 10 jobs max to avoid timeout
const limited = allItems.slice(0, 10);

const formattedJobs = limited.map((item, index) => {
  const job = item.json;
  const cleanDesc = job.description
    ? job.description.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
    : 'No description provided';

  const salary = (job.salary_min && job.salary_max && job.salary_max > 0)
    ? `$${job.salary_min} - $${job.salary_max}`
    : 'Not specified';

  return `=== JOB ${index + 1} ===
Title: ${job.position || 'N/A'}
Company: ${job.company || 'N/A'}
Location: ${job.location || 'Remote'}
Salary: ${salary}
Apply: ${job.apply_url || job.url || 'N/A'}
Tags: ${job.tags ? job.tags.join(', ') : 'N/A'}
Description: ${cleanDesc.substring(0, 300)}
---`;
}).join('\n\n');

return [{
  json: {
    jobs_text: formattedJobs,
    total_jobs: limited.length
  }
}];

const agentOutput = $input.first().json.output || '';

// Build a clean HTML email
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto; color: #333; }
  h1 { background: #1a73e8; color: #fff; padding: 20px; border-radius: 6px; }
  h2 { color: #1a73e8; border-bottom: 2px solid #e8f0fe; padding-bottom: 6px; }
  .job { background: #f9f9f9; border: 1px solid #ddd; border-radius: 8px; padding: 16px; margin-bottom: 20px; }
  ul { padding-left: 20px; }
  li { margin-bottom: 6px; }
  a { color: #1a73e8; }
  .footer { color: #888; font-size: 12px; text-align: center; margin-top: 30px; }
</style>
</head>
<body>
  <h1>🚀 Daily Job Alert — ${today}</h1>
  <p>Here are today's matching remote jobs in AI, Python, and Data:</p>
  ${agentOutput}
  <div class="footer">Powered by Michael · Delivered daily </div>
</body>
</html>`;


return [{ json: { html_body: html, subject: `Job Alert: Remote AI & Python Jobs — ${today}` } }];

// Add this as a new Code node between HTTP Request and Filter
return $input.all()
  .filter(item => item.json.position) // skip the metadata first row
  .map(item => {
    const tags = (item.json.tags || []).join(',').toLowerCase();
    return {
      json: {
        ...item.json,
        tags_string: tags
      }
    };
  });
